/**
 * A simplified implementation of a stack using an array.
 */
public class ArrayStack {
    private int[] elements;
    private int top;
    private int capacity;

    /**
     * Constructs a stack with the specified capacity.
     * @param capacity The maximum capacity of the stack.
     */
    public ArrayStack(int capacity) {
        this.capacity = capacity;
        this.elements = new int[capacity];
        this.top = -1;
    }

    /**
     * Adds an element to the top of the stack.
     * @param element The element to be pushed onto the stack.
     * @throws IllegalStateException if the stack is full.
     */
    public void push(int element) {
        if (top == capacity - 1) {
            throw new IllegalStateException("Stack is full");
        }
        elements[++top] = element;
    }

    /**
     * Removes the element at the top of the stack and returns it.
     * @return The element removed from the top of the stack.
     * @throws IllegalStateException if the stack is empty.
     */
    public int pop() {
        if (isEmpty()) {
            throw new IllegalStateException("Stack is empty");
        }
        return elements[top--];
    }

    /**
     * Returns the element at the top of the stack without removing it.
     * @return The element at the top of the stack.
     * @throws IllegalStateException if the stack is empty.
     */
    public int peek() {
        if (isEmpty()) {
            throw new IllegalStateException("Stack is empty");
        }
        return elements[top];
    }

    /**
     * Checks if the stack is empty.
     * @return true if the stack is empty, false otherwise.
     */
    public boolean isEmpty() {
        return top == -1;
    }
}

import java.lang.reflect.Constructor;
import java.lang.reflect.InvocationTargetException;
import java.util.HashMap;
import java.util.Map;

public class DependencyInjector {
    private Map<Class<?>, Object> components = new HashMap<>();

    public void registerComponent(Class<?> componentClass) {
        if (componentClass.isAnnotationPresent(Component.class)) {
            if (!components.containsKey(componentClass)) {
                try {
                    Constructor<?> constructor = componentClass.getDeclaredConstructor();
                    constructor.setAccessible(true);
                    Object instance = constructor.newInstance();
                    components.put(componentClass, instance);
                } catch (NoSuchMethodException | InstantiationException | IllegalAccessException | InvocationTargetException e) {
                    throw new DependencyInjectionException("Error registering component: " + e.getMessage());
                }
            } else {
                throw new DependencyInjectionException("Component " + componentClass.getName() + " is already registered");
            }
        } else {
            throw new DependencyInjectionException("Class " + componentClass.getName() + " is not annotated with @Component");
        }
    }

    public <T> T getComponent(Class<T> componentClass) {
        if (components.containsKey(componentClass)) {
            return componentClass.cast(components.get(componentClass));
        } else {
            throw new DependencyInjectionException("Component " + componentClass.getName() + " is not registered");
        }
    }
}

public class DependencyInjectionException extends RuntimeException {
    public DependencyInjectionException(String message) {
        super(message);
    }
}

