    private String maskCreditCardNumbers(String line) {
        Pattern pattern = Pattern.compile("\\b\\d{4}-\\d{4}-\\d{4}-\\d{4}\\b");
        Matcher matcher = pattern.matcher(line);
        return matcher.replaceAll("XXXX-XXXX-XXXX-XXXX");
    }

    private String maskEmailAddresses(String line) {
        Pattern pattern = Pattern.compile("\\b[\\w.-]+@[\\w.-]+\\.[a-zA-Z]{2,6}\\b");
        Matcher matcher = pattern.matcher(line);
        return matcher.replaceAll("*****@*****");
    }
}

