import java.util.Deque;
import java.util.LinkedList;

public class AbsolutePathResolver {
    public String getAbsolutePath(String path) {
        Deque<String> stack = new LinkedList<>();
        String[] components = path.split("/");

        for (String component : components) {
            if (component.equals("..")) {
                if (!stack.isEmpty()) {
                    stack.pop();
                }
            } else if (!component.equals(".") && !component.isEmpty()) {
                stack.push(component);
            }
        }

        StringBuilder absolutePath = new StringBuilder();
        for (String dir : stack) {
            absolutePath.insert(0, "/" + dir);
        }

        return absolutePath.length() > 0 ? absolutePath.toString() : "/";
    }

    public static void main(String[] args) {
        AbsolutePathResolver resolver = new AbsolutePathResolver();
        System.out.println(resolver.getAbsolutePath("/usr/bin/../local/./bin")); // Output: /usr/local/bin
        System.out.println(resolver.getAbsolutePath("/home/user/documents/../photos/./vacation")); // Output: /home/user/photos/vacation
    }
}

