import java.io.*;

public class ArraySerializer {
    // Implement the serialization method to write the array to a binary file
    public void serialize(int[] array, String fileName) {
        try (DataOutputStream dos = new DataOutputStream(new FileOutputStream(fileName))) {
            dos.writeInt(array.length);
            for (int value : array) {
                dos.writeInt(value);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    // Implement the deserialization method to read the binary file and reconstruct the original array
    public int[] deserialize(String fileName) {
        try (DataInputStream dis = new DataInputStream(new FileInputStream(fileName))) {
            int length = dis.readInt();
            int[] array = new int[length];
            for (int i = 0; i < length; i++) {
                array[i] = dis.readInt();
            }
            return array;
        } catch (IOException e) {
            e.printStackTrace();
            return new int[0];
        }
    }

    public static void main(String[] args) {
        int[] originalArray = {1, 2, 3, 4, 5};
        ArraySerializer serializer = new ArraySerializer();
        serializer.serialize(originalArray, "serializedArray.bin");
        int[] deserializedArray = serializer.deserialize("serializedArray.bin");
        for (int value : deserializedArray) {
            System.out.print(value + " ");
        }
    }
}

