import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;

import java.io.File;
import java.io.IOException;
import java.time.LocalDateTime;

public class EquinoxProcessor {
    public static void main(String[] args) {
        File input = new File("equinoxes.xml");
        try {
            Document doc = Jsoup.parse(input, "UTF-8", "");
            Element equinoxElement = doc.select("equinox").first();
            LocalDateTime equinoxDate = generateEquinoxDate(equinoxElement);
            System.out.println("Equinox date: " + equinoxDate);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static LocalDateTime generateEquinoxDate(Element e) {
        int year = Integer.parseInt(e.select("year").text());
        String dateStr = e.select("date").text();
        String[] dateParts = dateStr.split("-");
        int month = Integer.parseInt(dateParts[1]);
        int day = Integer.parseInt(dateParts[2]);
        return LocalDateTime.of(year, month, day, 0, 0);
    }
}

