public class ParenthesesChecker {
    public static boolean isValidParentheses(String s) {
        int count = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') {
                count++;
            } else if (c == ')') {
                if (count == 0) {
                    return false; // More right parentheses than left parentheses
                }
                count--;
            }
        }
        return count == 0; // Return true if count is 0 (equal number of left and right parentheses)
