    private Map<FoodItem, Integer> items;

    public Order() {
        items = new HashMap<>();
    }

    public void addFoodItem(FoodItem foodItem, int quantity) {
        items.put(foodItem, items.getOrDefault(foodItem, 0) + quantity);
