    public static float[] calculateAverageDistortion(float[] distortionMatrix) {
        int rows = 4;
        int columns = 4;
        float[] rowDistortion = new float[rows];
        float[] columnDistortion = new float[columns];

        for (int i = 0; i < rows; i++) {
            float sum = 0;
            for (int j = 0; j < columns; j++) {
                sum += distortionMatrix[i * columns + j];
            }
            rowDistortion[i] = sum / columns;
