import javax.websocket.Session;
import java.io.IOException;
import java.util.List;
import java.util.Map;
import java.util.concurrent.*;

public class SessionManager {
    private static final ScheduledExecutorService threadPool = Executors.newScheduledThreadPool(5);

    public void sendMessageToSessions(String message, ConcurrentHashMap<String, List<Session>> sessionMap) {
        threadPool.scheduleAtFixedRate(() -> {
            sessionMap.forEach((userId, sessions) -> {
                for (Session session : sessions) {
                    try {
                        session.getBasicRemote().sendText(message);
                    } catch (IOException e) {
                        e.printStackTrace();
                    }
                }
            });
        }, 0, 1, TimeUnit.SECONDS);
    }
}

