import java.io.*;
import java.util.*;

public class CifarLoader {
    private List<int[][][]> images; // List to store image data
    private List<Integer> labels; // List to store image labels

    public CifarLoader(int row, int col, int channels, String path, boolean shuffle, boolean normalize, boolean oneHotLabel) {
        // Load CIFAR-10 data from file
        try {
            DataInputStream dataIn = new DataInputStream(new FileInputStream(path));
            images = new ArrayList<>();
            labels = new ArrayList<>();

            for (int i = 0; i < 60000; i++) {
                byte[] imageBuffer = new byte[row * col * channels];
                dataIn.readFully(imageBuffer);
                int[][][] image = new int[channels][row][col];
                for (int c = 0; c < channels; c++) {
                    for (int r = 0; r < row; r++) {
                        for (int j = 0; j < col; j++) {
                            image[c][r][j] = imageBuffer[c * row * col + r * col + j] & 0xff; // Convert byte to unsigned int
                        }
                    }
                }
                images.add(image);
                labels.add(dataIn.readUnsignedByte());
            }
            dataIn.close();
        } catch (IOException e) {
            e.printStackTrace();
        }

        // Shuffle the dataset if required
        if (shuffle) {
            long seed = System.nanoTime();
            Collections.shuffle(images, new Random(seed));
            Collections.shuffle(labels, new Random(seed));
        }

        // Normalize the dataset if required
        if (normalize) {
            for (int[][][] image : images) {
                for (int c = 0; c < channels; c++) {
                    for (int r = 0; r < row; r++) {
                        for (int j = 0; j < col; j++) {
                            image[c][r][j] = (image[c][r][j] - 128) / 128; // Normalize pixel values to range [-1, 1]
                        }
                    }
                }
            }
        }

        // Perform one-hot encoding for labels if required
        if (oneHotLabel) {
            List<Integer> uniqueLabels = new ArrayList<>(new HashSet<>(labels));
            int numClasses = uniqueLabels.size();
            List<int[]> oneHotLabels = new ArrayList<>();
            for (int label : labels) {
                int[] oneHot = new int[numClasses];
                oneHot[uniqueLabels.indexOf(label)] = 1;
                oneHotLabels.add(oneHot);
            }
            labels.clear();
            labels.addAll(oneHotLabels);
        }
    }

    // Other methods for accessing the loaded data and labels can be implemented here
}

