public int[] countSetBits(int[] inputArray) {
    int[] bitCountArray = new int[inputArray.length];
    for (int i = 0; i < inputArray.length; i++) {
        int num = inputArray[i];
        int count = 0;
        while (num > 0) {
            count += num & 1;
            num >>= 1;
        }
        bitCountArray[i] = count;
    }
