import javax.annotation.processing.AbstractProcessor;
import javax.annotation.processing.RoundEnvironment;
import javax.annotation.processing.SupportedAnnotationTypes;
import javax.annotation.processing.SupportedSourceVersion;
import javax.lang.model.SourceVersion;
import javax.lang.model.element.Element;
import javax.lang.model.element.TypeElement;
import javax.tools.Diagnostic;
import javax.tools.JavaFileObject;
import javax.lang.model.element.AnnotationMirror;
import javax.lang.model.element.AnnotationValue;
import javax.lang.model.element.PackageElement;
import javax.lang.model.util.Elements;
import javax.lang.model.util.Types;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Set;

@SupportedAnnotationTypes("java.lang.annotation.Retention")
@SupportedSourceVersion(SourceVersion.RELEASE_8)
public class RetentionAnnotationProcessor extends AbstractProcessor {

    @Override
    public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
        Elements elementUtils = processingEnv.getElementUtils();
        Types typeUtils = processingEnv.getTypeUtils();

        for (Element element : roundEnv.getElementsAnnotatedWith(Retention.class)) {
            if (element instanceof TypeElement) {
                TypeElement typeElement = (TypeElement) element;
                PackageElement packageElement = elementUtils.getPackageOf(typeElement);
                String packageName = packageElement.getQualifiedName().toString();
                String className = typeElement.getQualifiedName().toString();
                AnnotationMirror annotationMirror = getRetentionAnnotationMirror(typeElement);
                AnnotationValue retentionValue = getRetentionValue(annotationMirror);
                String retentionPolicy = retentionValue.getValue().toString();

                generateReport(packageName, className, retentionPolicy);
            }
        }
        return true;
    }

    private AnnotationMirror getRetentionAnnotationMirror(TypeElement typeElement) {
        for (AnnotationMirror annotationMirror : typeElement.getAnnotationMirrors()) {
            if (annotationMirror.getAnnotationType().toString().equals("java.lang.annotation.Retention")) {
                return annotationMirror;
            }
        }
        return null;
    }

    private AnnotationValue getRetentionValue(AnnotationMirror annotationMirror) {
        for (AnnotationValue annotationValue : annotationMirror.getElementValues().values()) {
            return annotationValue;
        }
        return null;
    }

    private void generateReport(String packageName, String className, String retentionPolicy) {
        try {
            JavaFileObject fileObject = processingEnv.getFiler().createSourceFile("RetentionReport");
            try (PrintWriter writer = new PrintWriter(fileObject.openWriter())) {
                writer.println("Annotated Class: " + className);
                writer.println("Package: " + packageName);
                writer.println("Retention Policy: " + retentionPolicy);
            }
        } catch (IOException e) {
            processingEnv.getMessager().printMessage(Diagnostic.Kind.ERROR, "Error creating report file");
        }
    }
}

