public Rectangle corridor() {
    int rows = floorPlan.length;
    int cols = floorPlan[0].length;
    int[][] dp = new int[rows][cols];

    int maxLen = 0;
    int top = 0, left = 0, bottom = 0, right = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (floorPlan[i][j] == 1) {
                if (i > 0 && floorPlan[i - 1][j] == 1) {
                    dp[i][j] = dp[i - 1][j] + 1;
                }
                if (j > 0 && floorPlan[i][j - 1] == 1) {
                    dp[i][j] = Math.max(dp[i][j], dp[i][j - 1] + 1);
                }
                if (dp[i][j] > maxLen) {
                    maxLen = dp[i][j];
                    top = i - maxLen + 1;
                    left = j - maxLen + 1;
                    bottom = i;
                    right = j;
                }
            }
        }
    }

    return new Rectangle(top, left, bottom, right);
}

