public class BarChartPositioner {
    public List<Double> positionBars(List<Double> barHeights) {
        List<Double> positions = new ArrayList<>();

        int numBars = barHeights.size();
        double barWidth = 1.0 / (numBars + 1); // Calculate the width of each bar

