public class Fibonacci {
    public static int iterativeFibonacci(int n) {
        if (n <= 1) {
            return n;
        }
        int prev = 0;
        int curr = 1;
        for (int i = 2; i <= n; i++) {
            int next = prev + curr;
            prev = curr;
            curr = next;
        }
        return curr;
    }

    public static void main(String[] args) {
        int n = 6;
        System.out.println(iterativeFibonacci(n)); // Output: 8
    }
}

