import java.util.HashMap;
import java.util.Map;

public class SimplifiedDataStructure {
    private Map<String, Integer> elementCount;

    public SimplifiedDataStructure() {
        elementCount = new HashMap<>();
    }

    public void add(String element) {
        elementCount.put(element, elementCount.getOrDefault(element, 0) + 1);
    }

    public void remove(String element) {
        if (elementCount.containsKey(element)) {
            int count = elementCount.get(element);
            if (count == 1) {
                elementCount.remove(element);
            } else {
                elementCount.put(element, count - 1);
            }
        }
    }

    public int count(String element) {
        return elementCount.getOrDefault(element, 0);
    }

