public class IntentScheduler {
    private AlarmManager alarmManager;
    private Context context;

    public IntentScheduler(Context context) {
        this.context = context;
        this.alarmManager = (AlarmManager) context.getSystemService(Context.ALARM_SERVICE);
    }

    public void scheduleIntent(long index, long delayInMillis, Bundle content) {
        PendingIntent pendingIntent = getPendingIntent(index, content);
        scheduleAlarm(delayInMillis, pendingIntent);
    }

    public void unscheduleIntent(int index) {
        alarmManager.cancel(getPendingIntent(index, null));
    }

    private PendingIntent getPendingIntent(long index, Bundle content) {
        Intent intent = new Intent(context, YourBroadcastReceiver.class);
        if (content != null) {
            intent.putExtras(content);
        }
        return PendingIntent.getBroadcast(context, (int) index, intent, PendingIntent.FLAG_UPDATE_CURRENT);
    }

    private void scheduleAlarm(long delayInMillis, PendingIntent pendingIntent) {
        if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.M) {
            alarmManager.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP, System.currentTimeMillis() + delayInMillis, pendingIntent);
