        return ResponseEntity.status(400).body("Malformed request body");
    }

    @ExceptionHandler(CustomApplicationException.class)
    public ResponseEntity<String> handleCustomApplicationException(CustomApplicationException ex, NativeWebRequest request) {
        logger.error("Custom Application Exception: " + ex.getMessage());
        return ResponseEntity.status(422).body("Custom application exception occurred");
    }
}

