public static boolean isIsomorphic(String[] arr1, String[] arr2) {
    if (arr1.length != arr2.length) {
        return false; // If the arrays have different lengths, they cannot be isomorphic
    }

    Map<String, String> mapping = new HashMap<>();
    Set<String> mappedValues = new HashSet<>();

    for (int i = 0; i < arr1.length; i++) {
        String key = arr1[i];
        String value = arr2[i];

        if (mapping.containsKey(key)) {
            if (!mapping.get(key).equals(value)) {
                return false; // If the key is already mapped to a different value, the arrays are not isomorphic
            }
        } else {
            if (mappedValues.contains(value)) {
                return false; // If the value is already mapped to a different key, the arrays are not isomorphic
            }
            mapping.put(key, value);
            mappedValues.add(value);
        }
    }

    return true; // If no violations are found, the arrays are isomorphic
}

