public class BillingService {
    private final ClienteRepository clienteRepository;
    private final ServicoPrestadoRepository repository;
    private final BigDecimalConverter bigDecimalConverter;

    public BillingService(ClienteRepository clienteRepository, ServicoPrestadoRepository repository, BigDecimalConverter bigDecimalConverter) {
        this.clienteRepository = clienteRepository;
        this.repository = repository;
        this.bigDecimalConverter = bigDecimalConverter;
    }

    public BigDecimal calculateTotalBill(Long clientId) {
        Cliente cliente = clienteRepository.findClienteById(clientId);
        List<ServicoPrestado> servicos = repository.findServicosByClienteId(clientId);

        BigDecimal totalBill = BigDecimal.ZERO;
        for (ServicoPrestado servico : servicos) {
            BigDecimal valor = bigDecimalConverter.convert(servico.getValor());
            totalBill = totalBill.add(valor);
        }

        return totalBill;
    }
}

