public class MS_Cipher {
    private String algorithm;
    private String key;

    private MS_Cipher(String algorithm, String key) {
        this.algorithm = algorithm;
        this.key = key;
    }

    public static MS_CipherBuilder createCipher() {
        return new MS_CipherBuilder();
    }

    public String encrypt(String message) throws Exception {
        Cipher cipher = Cipher.getInstance(algorithm);
        SecretKeySpec secretKey = new SecretKeySpec(key.getBytes(), algorithm);
        cipher.init(Cipher.ENCRYPT_MODE, secretKey);
        byte[] encryptedBytes = cipher.doFinal(message.getBytes());
        return new String(encryptedBytes);
    }

    public String decrypt(String encryptedMessage) throws Exception {
        Cipher cipher = Cipher.getInstance(algorithm);
        SecretKeySpec secretKey = new SecretKeySpec(key.getBytes(), algorithm);
        cipher.init(Cipher.DECRYPT_MODE, secretKey);
        byte[] decryptedBytes = cipher.doFinal(encryptedMessage.getBytes());
        return new String(decryptedBytes);
    }
}

class MS_CipherBuilder {
    private String algorithm;
    private String key;

    public MS_CipherBuilder setAlgorithm(String algorithm) {
        this.algorithm = algorithm;
        return this;
    }

    public MS_CipherBuilder setKey(String key) {
        this.key = key;
        return this;
    }

    public MS_Cipher build() {
        return new MS_Cipher(algorithm, key);
