public class MenuFormatter {
    public static String generateFormattedMenu(MenuItemInfo[] menuItems) {
        Map<String, List<String>> menuMap = new TreeMap<>();

        for (MenuItemInfo menuItem : menuItems) {
            String[] parts = menuItem.getLabel().split("\\|");
            String category = parts[0].trim();
            String item = parts[1].trim();

            if (!menuMap.containsKey(category)) {
                menuMap.put(category, new ArrayList<>());
            }
            menuMap.get(category).add(item);
        }

        StringBuilder formattedMenu = new StringBuilder();
        for (Map.Entry<String, List<String>> entry : menuMap.entrySet()) {
            formattedMenu.append("- ").append(entry.getKey()).append("\n");
            Collections.sort(entry.getValue());
            for (String item : entry.getValue()) {
                formattedMenu.append("  - ").append(item).append("\n");
            }
        }

        return formattedMenu.toString();
    }

