public class AsciiDocDocumentAttributeScanner {

    public Map<String, String> extractAttributes(String input) {
        Map<String, String> attributes = new HashMap<>();
        Pattern pattern = Pattern.compile(":([\\w-]+):\\s*(.*?)\\s*(?=(?::[\\w-]+:)|$)", Pattern.DOTALL);
        Matcher matcher = pattern.matcher(input);

        while (matcher.find()) {
            String key = matcher.group(1);
            String value = matcher.group(2);
            attributes.put(key, value);
        }

        return attributes;
    }

    public static void main(String[] args) {
        AsciiDocDocumentAttributeScanner scanner = new AsciiDocDocumentAttributeScanner();
        String input = ":title: Sample Document\n:author: John Doe\n:version: 1.0\n:author: Jane Smith";
        Map<String, String> extractedAttributes = scanner.extractAttributes(input);
        System.out.println(extractedAttributes);
    }
}

