        mContext = context;
    }

    @Override
    public void onSurfaceCreated(GL10 gl, EGLConfig config) {
        // Initialize shader program
        mCube = new Cube();
        mCube.loadTexture(mContext); // Load texture
        GLES20.glEnable(GLES20.GL_DEPTH_TEST); // Enable depth testing
    }

    @Override
    public void onSurfaceChanged(GL10 gl, int width, int height) {
        GLES20.glViewport(0, 0, width, height); // Update the viewport
        float ratio = (float) width / height;
        Matrix.frustumM(mProjectionMatrix, 0, -ratio, ratio, -1, 1); // Update the projection matrix
    }

    @Override
    public void onDrawFrame(GL10 gl) {
        GLES20.glClear(GLES20.GL_COLOR_BUFFER_BIT | GLES20.GL_DEPTH_BUFFER_BIT); // Clear the color and depth buffers

        Matrix.setLookAtM(mViewMatrix, 0, 0, 0, -3, 0f, 0f, 0f, 0f, 1.0f, 0.0f); // Set the view matrix

        long time = SystemClock.uptimeMillis() % 4000L;
        float angle = 0.090f * ((int) time);
        Matrix.setIdentityM(mMVPMatrix, 0);
        Matrix.rotateM(mMVPMatrix, 0, angle, 0, 1, 0); // Set the model-view matrix

        mCube.draw(mMVPMatrix, mProjectionMatrix, mViewMatrix); // Draw the cube
    }
}

