    }
    if (obj instanceof Map) {
        return formatMapToString((Map<?, ?>) obj, indentLevel);
    } else if (obj instanceof List) {
        return formatListToString((List<?>) obj, indentLevel);
    } else if (obj.getClass().isArray()) {
        return formatArrayToString(obj, indentLevel);
    } else {
        return obj.toString();
    }
}

private String formatMapToString(Map<?, ?> map, int indentLevel) {
    StringBuilder result = new StringBuilder();
    result.append("{\n");
    for (Map.Entry<?, ?> entry : map.entrySet()) {
        result.append(indent(indentLevel + 1)).append(entry.getKey()).append(": ");
        result.append(formatObjectToString(entry.getValue(), indentLevel + 1)).append(",\n");
    }
    result.append(indent(indentLevel)).append("}");
    return result.toString();
}

private String formatListToString(List<?> list, int indentLevel) {
    StringBuilder result = new StringBuilder();
    result.append("[\n");
    for (Object item : list) {
        result.append(indent(indentLevel + 1)).append(formatObjectToString(item, indentLevel + 1)).append(",\n");
    }
    result.append(indent(indentLevel)).append("]");
    return result.toString();
}

private String formatArrayToString(Object array, int indentLevel) {
    StringBuilder result = new StringBuilder();
    result.append("[\n");
    int length = Array.getLength(array);
    for (int i = 0; i < length; i++) {
        result.append(indent(indentLevel + 1)).append(formatObjectToString(Array.get(array, i), indentLevel + 1)).append(",\n");
    }
    result.append(indent(indentLevel)).append("]");
    return result.toString();
}

private String indent(int level) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < level * 4; i++) {
        sb.append(" ");
    }
    return sb.toString();
}

