public String convertToIfElse(String input) {
    String[] lines = input.split("\n");
    StringBuilder output = new StringBuilder("if (condition == ");
    int index = 0;
    for (String line : lines) {
        if (line.contains("WHEN")) {
            String[] parts = line.split("THEN");
            output.append(parts[0].trim().replace("WHEN", "")).append(") {\n");
            output.append("  ").append(parts[1].trim()).append("\n");
            if (index < lines.length - 2) {
                output.append("} else {\n");
                output.append("  if (condition == ");
            }
        } else if (line.contains("ELSE")) {
            String[] parts = line.split("ELSE");
            output.append(parts[1].trim()).append("\n");
            for (int i = 0; i < index; i++) {
                output.append("  ");
            }
            output.append("}");
        }
        index++;
    }
    return output.toString();
}

