    public void drawShape(Canvas canvas, String shapeType, int color) {
        Paint paint = new Paint();
        paint.setColor(color);
        paint.setStyle(Paint.Style.FILL);

        switch (shapeType) {
            case "circle":
                int centerX = canvas.getWidth() / 2;
                int centerY = canvas.getHeight() / 2;
                int radius = Math.min(centerX, centerY) - 20;
                canvas.drawCircle(centerX, centerY, radius, paint);
                break;
            case "square":
                int sideLength = Math.min(canvas.getWidth(), canvas.getHeight()) - 40;
                int left = (canvas.getWidth() - sideLength) / 2;
                int top = (canvas.getHeight() - sideLength) / 2;
                int right = left + sideLength;
                int bottom = top + sideLength;
                canvas.drawRect(left, top, right, bottom, paint);
                break;
            case "triangle":
                int halfWidth = canvas.getWidth() / 2;
                int halfHeight = canvas.getHeight() / 2;
                int triangleSize = Math.min(halfWidth, halfHeight) - 20;
                int x1 = halfWidth;
                int y1 = halfHeight - triangleSize;
                int x2 = halfWidth - (int) (triangleSize * Math.sqrt(3) / 2);
                int y2 = halfHeight + triangleSize / 2;
                int x3 = halfWidth + (int) (triangleSize * Math.sqrt(3) / 2);
                int y3 = halfHeight + triangleSize / 2;
