                    writer.println("import java.util.Map;");
                    writer.println("import java.util.HashMap;");
                    writer.println("public class " + className + "StorageHandler {");

                    for (Element field : classElement.getEnclosedElements()) {
                        if (field.getKind() == ElementKind.FIELD && field.getAnnotation(StorageReference.class) != null) {
                            String fieldName = field.getSimpleName().toString();
                            String fieldType = field.asType().toString();
                            boolean mapKey = field.getAnnotation(StorageReference.class).mapKey();
                            boolean mapValue = field.getAnnotation(StorageReference.class).mapValue();

                            if (mapKey) {
                                writer.println("private Map<String, " + fieldType + "> " + fieldName + "Map = new HashMap<>();");
                                writer.println("public void map" + fieldName + "(String key, " + fieldType + " value) {");
                                writer.println(fieldName + "Map.put(key, value);");
                                writer.println("}");
