import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;

public class PasswordHasher {
    private int saltHashLength;

    public int getSaltHashLength() {
        return saltHashLength;
    }

    public void setSaltHashLength(int saltHashLength) {
        this.saltHashLength = saltHashLength;
    }

    public String hashPassword(String password) {
        byte[] salt = generateSalt(saltHashLength);
        byte[] saltedPassword = concatenateByteArrays(salt, password.getBytes());
        byte[] hashedPassword = hashWithSHA256(saltedPassword);
        return bytesToHex(hashedPassword);
    }

    private byte[] generateSalt(int length) {
        byte[] salt = new byte[length];
        new SecureRandom().nextBytes(salt);
        return salt;
    }

    private byte[] concatenateByteArrays(byte[] a, byte[] b) {
        byte[] result = new byte[a.length + b.length];
        System.arraycopy(a, 0, result, 0, a.length);
        System.arraycopy(b, 0, result, a.length, b.length);
        return result;
    }

    private byte[] hashWithSHA256(byte[] input) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            return digest.digest(input);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("SHA-256 algorithm not available", e);
        }
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : bytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) {
                hexString.append('0');
            }
            hexString.append(hex);
        }
        return hexString.toString();
    }
}

public class Matrix {
    public int[] findMaxSubMatrix(int[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        int[] result = new int[4];
        int maxSum = Integer.MIN_VALUE;

        for (int left = 0; left < cols; left++) {
            int[] temp = new int[rows];
            for (int right = left; right < cols; right++) {
                for (int i = 0; i < rows; i++) {
                    temp[i] += matrix[i][right];
                }
                KadaneResult kadaneResult = kadane(temp);
                if (kadaneResult.maxSum > maxSum) {
                    maxSum = kadaneResult.maxSum;
                    result[0] = kadaneResult.start;
                    result[1] = left;
                    result[2] = kadaneResult.end;
                    result[3] = right;
                }
            }
        }
        return result;
    }

    private KadaneResult kadane(int[] arr) {
        int maxSoFar = arr[0];
        int maxEndingHere = arr[0];
        int start = 0;
        int end = 0;
        int tempStart = 0;

        for (int i = 1; i < arr.length; i++) {
            if (arr[i] > maxEndingHere + arr[i]) {
                maxEndingHere = arr[i];
                tempStart = i;
            } else {
                maxEndingHere += arr[i];
            }

            if (maxEndingHere > maxSoFar) {
                maxSoFar = maxEndingHere;
                start = tempStart;
                end = i;
            }
        }
        return new KadaneResult(maxSoFar, start, end);
    }

    private static class KadaneResult {
        int maxSum;
        int start;
        int end;

        KadaneResult(int maxSum, int start, int end) {
            this.maxSum = maxSum;
            this.start = start;
            this.end = end;
        }
    }
}

