import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class HeaderParser {

    public static List<String> extractDeveloperAndContributors(String filePath) {
        List<String> names = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            String line;
            StringBuilder headerComments = new StringBuilder();
            boolean inHeader = false;
            while ((line = reader.readLine()) != null) {
                if (line.trim().startsWith("/**")) {
                    inHeader = true;
                }
                if (inHeader) {
                    headerComments.append(line).append("\n");
                    if (line.trim().endsWith("*/")) {
                        break;
                    }
                }
            }
            String header = headerComments.toString();
            Pattern pattern = Pattern.compile("Initial developer\\(s\\): (.+)");
            Matcher matcher = pattern.matcher(header);
            if (matcher.find()) {
                String developers = matcher.group(1);
                names.addAll(List.of(developers.split(", ")));
            }
            pattern = Pattern.compile("Contributor\\(s\\): (.+)");
            matcher = pattern.matcher(header);
            if (matcher.find()) {
                String contributors = matcher.group(1);
                names.addAll(List.of(contributors.split(", ")));
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
        return names;
    }

    public static void main(String[] args) {
        String filePath = "path_to_your_java_file.java";
        List<String> names = extractDeveloperAndContributors(filePath);
        System.out.println(names);
    }
}

