import java.io.File;
import java.io.FileNotFoundException;
import java.util.*;

public class WordCounter {
    public static void main(String[] args) {
        File textFile = new File("input.txt");
        File stopWordsFile = new File("stopwords.txt");

        Map<String, Integer> wordCount = new HashMap<>();
        Set<String> stopWords = new HashSet<>();

        try (Scanner textScanner = new Scanner(textFile);
             Scanner stopWordsScanner = new Scanner(stopWordsFile)) {

            // Read stop words into set
            while (stopWordsScanner.hasNext()) {
                stopWords.add(stopWordsScanner.next().toLowerCase());
            }

            // Process text file
            while (textScanner.hasNext()) {
                String word = textScanner.next().toLowerCase();
                if (!stopWords.contains(word)) {
                    wordCount.put(word, wordCount.getOrDefault(word, 0) + 1);
                }
            }

            // Sort and output word counts
            List<Map.Entry<String, Integer>> sortedWordCount = new ArrayList<>(wordCount.entrySet());
            sortedWordCount.sort(Map.Entry.<String, Integer>comparingByValue().reversed());

            for (Map.Entry<String, Integer> entry : sortedWordCount) {
                System.out.println(entry.getKey() + ": " + entry.getValue());
            }

        } catch (FileNotFoundException e) {
            System.err.println("File not found: " + e.getMessage());
        }
    }
}

