import java.util.*;

class DirectedGraph {
    private Map<String, List<String>> adjacencyList;

    public DirectedGraph() {
        this.adjacencyList = new HashMap<>();
    }

    public void addNode(String nodeId) {
        if (!adjacencyList.containsKey(nodeId)) {
            adjacencyList.put(nodeId, new ArrayList<>());
        }
    }

    public void addEdge(String sourceNodeId, String targetNodeId) {
        if (adjacencyList.containsKey(sourceNodeId) && adjacencyList.containsKey(targetNodeId)) {
            adjacencyList.get(sourceNodeId).add(targetNodeId);
        } else {
            throw new IllegalArgumentException("Nodes not found in the graph");
        }
    }

    public List<String> getNodes() {
        return new ArrayList<>(adjacencyList.keySet());
    }

    public List<String> getNeighbors(String nodeId) {
        return adjacencyList.getOrDefault(nodeId, new ArrayList<>());
    }
}

