public void SetPosiciones(List<Object> objects) {
    int n = objects.size();
    List<Object> sortedObjects = new ArrayList<>(objects);
    sortedObjects.sort(Comparator.comparingInt(o -> o.X * n + o.Y));

    int[] dx = {0, 0, 1, -1};
    int[] dy = {1, -1, 0, 0};

    boolean[][] occupied = new boolean[n * 2][n * 2];
    int index = 0;

    for (Object obj : sortedObjects) {
        int bestX = 0, bestY = 0, minDist = Integer.MAX_VALUE;
        for (int x = 0; x < n * 2; x++) {
            for (int y = 0; y < n * 2; y++) {
                if (!occupied[x][y]) {
                    int dist = 0;
                    for (int k = 0; k < 4; k++) {
                        int nx = x + dx[k];
                        int ny = y + dy[k];
                        if (nx >= 0 && nx < n * 2 && ny >= 0 && ny < n * 2 && occupied[nx][ny]) {
                            dist += Math.abs(nx - obj.X) + Math.abs(ny - obj.Y);
                        }
                    }
                    if (dist < minDist) {
                        minDist = dist;
                        bestX = x;
                        bestY = y;
                    }
                }
            }
        }
        obj.X = bestX;
        obj.Y = bestY;
        occupied[bestX][bestY] = true;
        index++;
    }
}

