public int[][] filterResults(int[][] fullResults, int conditionColumn, int conditionValue) {
    int rowCount = 0;
    for (int i = 0; i < fullResults.length; i++) {
        if (fullResults[i][conditionColumn] == conditionValue) {
            rowCount++;
        }
    }

    int[][] filteredResults = new int[rowCount][fullResults[0].length];
