import java.util.HashMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class XmlParser {
    public static HashMap<String, String> parse(String xml) {
        HashMap<String, String> keyValueMap = new HashMap<>();
        Pattern entryPattern = Pattern.compile("<entry>\\s*<key>(.*?)</key>\\s*<value>(.*?)</value>\\s*</entry>");
        Matcher matcher = entryPattern.matcher(xml);

        while (matcher.find()) {
            String key = matcher.group(1);
            String value = matcher.group(2);
            keyValueMap.put(key, value);
        }

        return keyValueMap;
    }

    public static void main(String[] args) {
        String xml = "<entries>\n" +
                "    <entry>\n" +
                "        <key>name</key>\n" +
                "        <value>John Doe</value>\n" +
                "    </entry>\n" +
                "    <entry>\n" +
                "        <key>age</key>\n" +
                "        <value>30</value>\n" +
                "    </entry>\n" +
                "</entries>";

        HashMap<String, String> keyValueMap = parse(xml);
        System.out.println(keyValueMap); // Output: {name=John Doe, age=30}
    }
}

