import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

public class Message {
    private Map<String, Object> parameters;
    private Type type;

    public enum Type {
        PUB, SUB, UNSUB, PING
    }

    public Message(Type type) {
        this.type = type;
        this.parameters = new HashMap<>();
    }

    public Map<String, Object> getParameters() {
        return parameters;
    }

    public void setParameters(Map<String, Object> parameters) {
        this.parameters = parameters;
    }

    public Type getType() {
        return type;
    }
}

public class MessageBroker {
    private Map<Message.Type, Set<MessageSubscriber>> subscribers;

    public MessageBroker() {
        this.subscribers = new HashMap<>();
    }

    public void subscribe(Message.Type type, MessageSubscriber subscriber) {
        subscribers.computeIfAbsent(type, k -> new HashSet<>()).add(subscriber);
    }

    public void unsubscribe(Message.Type type, MessageSubscriber subscriber) {
        subscribers.getOrDefault(type, new HashSet<>()).remove(subscriber);
    }

    public void publish(Message message) {
        Set<MessageSubscriber> messageSubscribers = subscribers.getOrDefault(message.getType(), new HashSet<>());
        for (MessageSubscriber subscriber : messageSubscribers) {
            subscriber.receiveMessage(message);
        }
    }
}

public interface MessageSubscriber {
    void receiveMessage(Message message);
}

