public class PermissionChecker {
    public static final String[] PERMISSION_FOR_EXPORT = new String[]{
            Manifest.permission.WRITE_EXTERNAL_STORAGE,
            com.ichi2.anki.api.AddContentApi.READ_WRITE_PERMISSION
