public class CartesianPoint {
    public float x;
    public float y;

    // Constructor to initialize the point with given x and y coordinates
    public CartesianPoint(float x, float y) {
        this.x = x;
        this.y = y;
    }

    // Method to calculate the distance between two points
    public float distanceTo(CartesianPoint other) {
        float dx = this.x - other.x;
        float dy = this.y - other.y;
        return (float) Math.sqrt(dx * dx + dy * dy);
    }

    // Method to calculate the midpoint between two points
    public CartesianPoint midpointWith(CartesianPoint other) {
        float midX = (this.x + other.x) / 2;
        float midY = (this.y + other.y) / 2;
