import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;

public class PolygonSorter {
    public ArrayList<Polygon> sortByPerimeter(ArrayList<Polygon> polygonArrayList) throws Exception {
        if (polygonArrayList.isEmpty()) {
            return new ArrayList<>();
        }

        for (Polygon polygon : polygonArrayList) {
            if (polygon.getSideLengths().size() < 3) {
                throw new Exception("Invalid polygon: less than 3 sides");
            }
        }

        Collections.sort(polygonArrayList, Comparator.comparingDouble(this::calculateTotalPerimeter));

        return polygonArrayList;
    }

    private double calculateTotalPerimeter(Polygon polygon) {
        return polygon.getSideLengths().stream().mapToDouble(Double::doubleValue).sum();
    }
}

