public int longestSubstring(String s) {
    int n = s.length();
    int result = 0;
    int[] index = new int[128]; // Assuming ASCII characters

    for (int j = 0, i = 0; i < n; i++) {
        j = Math.max(index[s.charAt(i)], j);
        result = Math.max(result, i - j + 1);
        index[s.charAt(i)] = i + 1;
    }

    return result;
}

