public class TimeZoneConverter {
    public String convertTime(String time, String sourceTimeZone, String targetTimeZone) {
        LocalTime localTime = LocalTime.parse(time);
        ZoneOffset sourceOffset = ZoneOffset.of(sourceTimeZone.substring(3));
        ZoneOffset targetOffset = ZoneOffset.of(targetTimeZone.substring(3));
        LocalTime convertedTime = localTime.plusSeconds(sourceOffset.getTotalSeconds() - targetOffset.getTotalSeconds());
        return convertedTime.toString();
    }

    public int getTimeDifference(String timeZone1, String timeZone2) {
        ZoneOffset offset1 = ZoneOffset.of(timeZone1.substring(3));
        ZoneOffset offset2 = ZoneOffset.of(timeZone2.substring(3));
        return offset2.getTotalSeconds() / 3600 - offset1.getTotalSeconds() / 3600;
    }
}

