import java.util.ArrayList;
import java.util.List;

public class MergeOrderedFeatures {

    public List<String> merge(List<String> list1, List<String> list2) {
        List<String> mergedList = new ArrayList<>();

        int index1 = 0, index2 = 0;

        while (index1 < list1.size() && index2 < list2.size()) {
            String element1 = list1.get(index1);
            String element2 = list2.get(index2);

            if (element1.equals(element2)) {
                mergedList.add(element1);
                index1++;
                index2++;
            } else if (list1.subList(index1 + 1, list1.size()).contains(element2)) {
                mergedList.add(element1);
                index1++;
            } else if (list2.subList(index2 + 1, list2.size()).contains(element1)) {
                mergedList.add(element2);
                index2++;
            } else {
                mergedList.add(element1);
                mergedList.add(element2);
                index1++;
                index2++;
            }
        }

        while (index1 < list1.size()) {
            mergedList.add(list1.get(index1));
            index1++;
        }

        while (index2 < list2.size()) {
            mergedList.add(list2.get(index2));
            index2++;
        }

        return mergedList;
    }
}

