public String formatTimestamp(String timestamp) {
    String[] components = timestamp.split(":");
    StringBuilder formattedTimestamp = new StringBuilder();

    for (String component : components) {
        while (component.length() < 2) {
            component = "0" + component;
        }
        formattedTimestamp.append(component).append(":");
    }

    formattedTimestamp.deleteCharAt(formattedTimestamp.length() - 1); // Remove the extra ":" at the end
    return formattedTimestamp.toString();
}

