     * Initialize the aliased fields for this table alias
     */
    private List<String> init(Map<String, String> fieldAliases) {
        List<String> initializedFields = new ArrayList<>();
        for (Map.Entry<String, String> entry : fieldAliases.entrySet()) {
            String fieldName = entry.getKey();
            String aliasName = entry.getValue();
            if (wrapInParentheses) {
                initializedFields.add(aliasName + "." + fieldName);
            } else {
                initializedFields.add(aliasName);
            }
        }
        return initializedFields;
    }
}

