    }

    // Method to calculate the distance between the current point and another given point
    public double distanceTo(PointWithOffset otherPoint) {
        float dx = this.x - otherPoint.getX() + this.xOffset - otherPoint.xOffset;
        float dy = this.y - otherPoint.getY() + this.yOffset - otherPoint.yOffset;
        return Math.sqrt(dx * dx + dy * dy);
    }
}

