@RequestMapping("/socks")
public class SocksController {

    @Autowired
    private SocksService socksService;

    @PostMapping("/add")
    public ResponseEntity<String> addSocks(@Valid @RequestBody Socks socks) {
        if (socksService.addSocks(socks)) {
            return ResponseEntity.ok("Socks added successfully");
        } else {
            return ResponseEntity.badRequest().body("Failed to add socks");
        }
    }

    @GetMapping("/total")
    public ResponseEntity<Integer> getTotalSocks(
            @RequestParam("color") @Pattern(regexp = "^red|blue|green$") String color,
            @RequestParam("cottonPart") @Pattern(regexp = "^\\d{1,3}%$") String cottonPart,
            @RequestParam("operation") @Pattern(regexp = "^moreThan|lessThan|equal$") String operation) {
        int totalSocks = socksService.getTotalSocksByColorAndCottonPart(color, cottonPart, operation);
        return ResponseEntity.ok(totalSocks);
    }
}

