                        printNestedObjectProperties(value, field.getName());
                    }
                }
            } catch (IllegalAccessException e) {
                e.printStackTrace();
            }
        }
    }

    private static void printNestedObjectProperties(Object obj, String prefix) {
        Class<?> objClass = obj.getClass();
        Field[] fields = objClass.getDeclaredFields();
        for (Field field : fields) {
            field.setAccessible(true);
            try {
                Object value = field.get(obj);
                if (value != null) {
                    if (value.getClass().getName().startsWith("java")) {
                        System.out.println(prefix + "." + field.getName() + ": " + value);
                    } else {
                        printNestedObjectProperties(value, prefix + "." + field.getName());
                    }
                }
            } catch (IllegalAccessException e) {
                e.printStackTrace();
            }
        }
    }
}

