public boolean isPalindrome(String s) {
    s = s.replaceAll("[^a-zA-Z0-9]", "").toLowerCase(); // Remove non-alphanumeric characters and convert to lowercase
    int left = 0, right = s.length() - 1;

    while (left < right) {
        if (s.charAt(left) != s.charAt(right)) {
            return false; // Not a palindrome
        }
        left++;
        right--;
    }
    return true; // Input string is a palindrome
}

public Rect calculateUVCoordinates(int textureId, TextureMapper textureMapper) {
    TextureMapper.TextureMap textureMap = textureMapper.map[(byte)textureId];
    TextureMapper.TextureMap.Face face = textureMap.front;

    float left = 1.0f / 128 * face.bl.x * 16;
    float top = 1 - (1.0f / 128 * face.bl.y * 16);
    float right = left + 1.0f / 128 * 16;
    float bottom = top + 1.0f / 128 * 16;

    return new Rect(left, top, right, bottom);
}

