        return new NodeEvaluator[]{
                new LogicNodeEvaluator(),
                new MemberNodeEvaluator(),
                new EscapeNodeEvaluator(),
                new ConcatenationNodeEvaluator(),
                new MathNodeEvaluator()
        };
    }

    private Class<? extends Node> getSupportedNodeType(NodeEvaluator evaluator) {
        if (evaluator instanceof LogicNodeEvaluator) {
            return LogicNode.class;
        } else if (evaluator instanceof MemberNodeEvaluator) {
            return MemberNode.class;
        } else if (evaluator instanceof EscapeNodeEvaluator) {
            return EscapeNode.class;
        } else if (evaluator instanceof ConcatenationNodeEvaluator) {
            return ConcatenationNode.class;
        } else if (evaluator instanceof MathNodeEvaluator) {
            return MathNode.class;
        }
        throw new IllegalArgumentException("Unsupported NodeEvaluator type");
