import javax.tools.Diagnostic;
import javax.tools.JavaFileObject;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Set;

@SupportedAnnotationTypes("com.rackspace.papi.service.datastore.impl.ehcache.ManagedResource")
@SupportedSourceVersion(SourceVersion.RELEASE_8)
public class MBeanAnnotationProcessor extends AbstractProcessor {

    @Override
    public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
        for (Element element : roundEnv.getElementsAnnotatedWith(ManagedResource.class)) {
            if (element instanceof TypeElement) {
                TypeElement typeElement = (TypeElement) element;
                String mBeanName = typeElement.getSimpleName() + "MBean";
                String packageName = processingEnv.getElementUtils().getPackageOf(typeElement).getQualifiedName().toString();

                try {
                    JavaFileObject fileObject = processingEnv.getFiler().createSourceFile(packageName + "." + mBeanName);
                    try (PrintWriter writer = new PrintWriter(fileObject.openWriter())) {
                        writer.println("package " + packageName + ";");
                        writer.println();
                        writer.println("import javax.management.*;");
                        writer.println();
                        writer.println("@MBean(description = \"" + typeElement.getAnnotation(ManagedResource.class).description() + "\")");
                        writer.println("public interface " + mBeanName + " {");

                        for (VariableElement variableElement : ElementFilter.fieldsIn(typeElement.getEnclosedElements())) {
                            writer.println("    @ManagedAttribute(description = \"" + variableElement.getSimpleName() + "\")");
                            writer.println("    " + variableElement.asType() + " get" + variableElement.getSimpleName() + "();");
                            writer.println("    void set" + variableElement.getSimpleName() + "(" + variableElement.asType() + " " + variableElement.getSimpleName() + ");");
                        }

                        writer.println("}");
                    }
                } catch (IOException e) {
                    processingEnv.getMessager().printMessage(Diagnostic.Kind.ERROR, "Error creating MBean interface: " + e.getMessage());
                }
            }
        }
        return true;
    }
}

