import java.util.*;

public class RouterNetwork {
    private List<Router> routers;

    public RouterNetwork(List<Router> routers) {
        this.routers = routers;
    }

    public List<Router> findShortestPath(Router source, Router destination) {
        Map<Router, Integer> distance = new HashMap<>();
        Map<Router, Router> previous = new HashMap<>();
        PriorityQueue<Router> queue = new PriorityQueue<>(Comparator.comparingInt(distance::get));

        for (Router router : routers) {
            distance.put(router, router == source ? 0 : Integer.MAX_VALUE);
            queue.add(router);
        }

        while (!queue.isEmpty()) {
            Router current = queue.poll();
            if (current == destination) {
                List<Router> path = new ArrayList<>();
                while (current != null) {
                    path.add(0, current);
                    current = previous.get(current);
                }
                return path;
            }

            for (Link link : current.getLinks()) {
                int alt = distance.get(current) + link.getWeight();
                if (alt < distance.get(link.getRouter())) {
                    distance.put(link.getRouter(), alt);
                    previous.put(link.getRouter(), current);
                    queue.remove(link.getRouter());
                    queue.add(link.getRouter());
                }
            }
        }

        return new ArrayList<>(); // No path found
    }
}

