public String getLongestCommonPrefix() {
    if (strings.isEmpty()) {
        return "";
    }

    String firstString = strings.first();
    String lastString = strings.last();

    int minLength = Math.min(firstString.length(), lastString.length());
    int commonPrefixLength = 0;

    for (int i = 0; i < minLength; i++) {
        if (firstString.charAt(i) != lastString.charAt(i)) {
            break;
        }
        commonPrefixLength++;
    }

    return firstString.substring(0, commonPrefixLength);
}

