    public <T> void serialize(T obj, String dir) {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(dir))) {
            oos.writeObject(obj);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

