    private HashSet<Integer> set;

    public UniqueStack() {
        stack = new Stack<>();
        set = new HashSet<>();
    }

    public void Push(int element) {
        if (!set.contains(element)) {
            stack.push(element);
            set.add(element);
        }
    }

    public Integer Pop() {
        if (!stack.isEmpty()) {
            int element = stack.pop();
            set.remove(element);
            return element;
        }
        return null;
    }

    public Integer Peek() {
        return stack.isEmpty() ? null : stack.peek();
    }

    public boolean IsEmpty() {
        return stack.isEmpty();
    }
}

