class CustomStack {
    private int[] stack;
    private int maxSize;
    private int size;

    public CustomStack(int maxSize) {
        this.maxSize = maxSize;
        this.stack = new int[maxSize];
        this.size = 0;
    }

    public void push(int x) {
        if (size < maxSize) {
            stack[size++] = x;
        }
    }

    public int pop() {
        if (size > 0) {
            return stack[--size];
        }
        return -1; // Stack is empty
    }

    public void increment(int k, int val) {
        int end = Math.min(k, size);
        for (int i = 0; i < end; i++) {
            stack[i] += val;
        }
    }
}

