public class ResourceNameProcessor {
    public List<String> getResourceNames(List<Integer> resourceIds, List<String> resourceTypes) {
        Map<String, Integer> resourceTypeMap = createResourceTypeMap();
        List<String> resourceNames = new ArrayList<>();

        for (int i = 0; i < resourceIds.size(); i++) {
            int resourceId = resourceIds.get(i);
            String resourceType = resourceTypes.get(i);
            String resourceName = getResourceName(resourceType, resourceId, resourceTypeMap);
            resourceNames.add(resourceName);
        }

        return resourceNames;
    }

    private Map<String, Integer> createResourceTypeMap() {
        Map<String, Integer> resourceTypeMap = new HashMap<>();
        resourceTypeMap.put("drawable", R.drawable.class);
        resourceTypeMap.put("layout", R.layout.class);
        resourceTypeMap.put("string", R.string.class);
        // Add more resource types as needed
        return resourceTypeMap;
    }

    private String getResourceName(String resourceType, int resourceId, Map<String, Integer> resourceTypeMap) {
        try {
            Class<?> resourceClass = resourceTypeMap.get(resourceType);
            if (resourceClass != null) {
                for (java.lang.reflect.Field field : resourceClass.getFields()) {
                    if (field.getType() == int.class && field.getInt(null) == resourceId) {
                        return field.getName();
                    }
                }
            }
        } catch (IllegalAccessException | IllegalArgumentException e) {
            e.printStackTrace();
        }
        return "Resource not found";
    }
}

public int getWeightAdjustment(Vector2Int distance, ObjectType objType) {
    int x = distance.x;
    int y = distance.y;

    switch (objType) {
        case SMALL:
            return Math.abs(x) + Math.abs(y);
        case MEDIUM:
            return Math.max(Math.abs(x), Math.abs(y));
        case LARGE:
            return Math.min(Math.abs(x), Math.abs(y));
        default:
            throw new IllegalArgumentException("Invalid object type");
    }
}

