public class TankTurretController {
    private double currentRotation; // Current rotation angle of the turret

    public TankTurretController(double initialRotation) {
        this.currentRotation = initialRotation;
    }

    public boolean adjustRotation(double targetRotation, double rotateSpeed) {
        double rotationDifference = targetRotation - currentRotation;

        if (Math.abs(rotationDifference) > rotateSpeed) {
            // Adjust the turret rotation without exceeding the rotateSpeed
            if (rotationDifference > 0) {
                currentRotation += rotateSpeed; // Rotate towards the target
