    for (String word : words) {
        result.append(new StringBuilder(word).reverse()).append(" "); // Reverse each word and append it to the result
    }

    return result.toString().trim(); // Remove trailing whitespace and return the modified string
}

public class CaseInsensitiveBufferEqualityComparator {
    private CaseInsensitiveBufferEqualityComparator() {
    }

    public static boolean areBuffersEqual(char[] buffer1, char[] buffer2) {
        if (buffer1.length != buffer2.length) {
            return false;
        }
        for (int i = 0; i < buffer1.length; i++) {
            if (Character.toLowerCase(buffer1[i]) != Character.toLowerCase(buffer2[i])) {
                return false;
            }
        }
        return true;
    }
}

