            accounts.put(accountNumber, new BankAccount(accountNumber));
        } else {
            System.out.println("Account with the given account number already exists.");
        }
    }

    public void depositFunds(String accountNumber, double amount) {
        BankAccount account = accounts.get(accountNumber);
        if (account != null) {
            account.deposit(amount);
        } else {
            System.out.println("Account not found.");
        }
    }

    public void withdrawFunds(String accountNumber, double amount) {
        BankAccount account = accounts.get(accountNumber);
        if (account != null) {
            account.withdraw(amount);
        } else {
            System.out.println("Account not found.");
        }
    }

    public void transferFunds(String sourceAccountNumber, String destinationAccountNumber, double amount) {
        BankAccount sourceAccount = accounts.get(sourceAccountNumber);
        BankAccount destinationAccount = accounts.get(destinationAccountNumber);
        if (sourceAccount != null && destinationAccount != null) {
            sourceAccount.transfer(destinationAccount, amount);
        } else {
            System.out.println("One or both accounts not found.");
        }
    }

    public void generateReport() {
