import java.nio.file.attribute.FileTime;
import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.time.Instant;
import java.time.format.DateTimeFormatter;
import java.time.temporal.ChronoUnit;

public class FileTimeConverter {
    private static final DateTimeFormatter rfc3339 = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss'Z'");
    private static final SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss'Z'");

    public static Instant ftToInstant(FileTime d) {
        try {
            String formattedTime = rfc3339.format(d.toInstant()).replaceAll("(\\d\\d)(\\d\\d)$", "$1:$2");
            return sdf.parse(formattedTime).toInstant().truncatedTo(ChronoUnit.SECONDS);
        } catch (ParseException e) {
            e.printStackTrace();
            return Instant.now().truncatedTo(ChronoUnit.SECONDS);
        }
    }
}

