import org.jetbrains.annotations.NotNull;

public class CustomPermissionProvider implements PermissionProvider {
    private boolean isAdmin; // Flag to indicate administrative privileges
    private boolean isReadOnly; // Flag to indicate read-only privileges

    public CustomPermissionProvider(boolean isAdmin, boolean isReadOnly) {
        this.isAdmin = isAdmin;
        this.isReadOnly = isReadOnly;
    }

    @NotNull
    @Override
    public RepositoryPermission getRepositoryPermission() {
        if (isAdmin) {
            return RepositoryPermission.ALL;
        } else if (isReadOnly) {
            return RepositoryPermission.READ_ONLY;
        } else {
            return RepositoryPermission.NONE;
        }
    }

    @NotNull
    @Override
    public TreePermission getTreePermission(@NotNull Tree tree, @NotNull TreePermission parentPermission) {
        if (parentPermission == TreePermission.ALL) {
            return TreePermission.ALL;
        } else if (parentPermission == TreePermission.READ_ONLY) {
            return TreePermission.READ_ONLY;
        } else {
            return TreePermission.NONE;
        }
    }
}

