import java.util.Arrays;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class WordCounter {
    public static void main(String[] args) {
        List<String> strings = Arrays.asList("The cat is on the mat.", "Cats are cute!", "category");
        String word = "cat";
        int occurrences = countWordOccurrences(strings, word);
        System.out.println("Total occurrences of the word '" + word + "': " + occurrences);
    }

    public static int countWordOccurrences(List<String> strings, String word) {
        int count = 0;
        String pattern = "\\b" + word + "\\b";
        Pattern p = Pattern.compile(pattern, Pattern.CASE_INSENSITIVE);

        for (String s : strings) {
            Matcher m = p.matcher(s);
            while (m.find()) {
                count++;
            }
        }

        return count;
    }
}

import java.util.Collection;
import java.util.Optional;

import org.apache.commons.collections4.IteratorUtils;

public class CollectionProcessor {
    public static <T> Optional<T> processCollection(Collection<T> collection) {
        try {
            if (collection.isEmpty()) {
                return Optional.empty();
            } else if (collection.size() == 1) {
                return Optional.of(collection.iterator().next());
            } else {
                return Optional.of(IteratorUtils.get(collection.iterator(), 1));
            }
        } catch (Exception e) {
            // Handle any potential exceptions that may occur during processing
            System.err.println("An error occurred while processing the collection: " + e.getMessage());
            return Optional.empty();
        }
    }
}

