public int countPalindromes(String s) {
    int count = 0;
    for (int i = 0; i < s.length(); i++) {
        // Expand around the current character to find palindromic substrings with odd length
        count += expandAroundCenter(s, i, i);
        // Expand around the current character and its right neighbor to find palindromic substrings with even length
        count += expandAroundCenter(s, i, i + 1);
    }
    return count;
}

private int expandAroundCenter(String s, int left, int right) {
    int count = 0;
    while (left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right)) {
        count++;
        left--;
        right++;
    }
    return count;
}

