import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class FileHeaderExtractor {

    public static void main(String[] args) {
        String directoryPath = "path_to_directory"; // Replace with the actual directory path
        File directory = new File(directoryPath);
        if (directory.exists() && directory.isDirectory()) {
            File[] files = directory.listFiles((dir, name) -> name.endsWith(".java"));
            if (files != null) {
                for (File file : files) {
                    try {
                        extractFileHeaderInfo(file.toPath());
                    } catch (IOException e) {
                        System.err.println("Error reading file: " + file.getName());
                    }
                }
            } else {
                System.out.println("No Java files found in the directory.");
            }
        } else {
            System.err.println("Invalid directory path.");
        }
    }

    private static void extractFileHeaderInfo(Path filePath) throws IOException {
        List<String> lines = Files.readAllLines(filePath);
        StringBuilder header = new StringBuilder();
        for (String line : lines) {
            if (line.trim().startsWith("/*")) {
                header.append(line).append("\n");
            } else if (line.trim().startsWith("*")) {
                header.append(line).append("\n");
            } else if (line.trim().startsWith("*/")) {
                header.append(line);
                break;
            } else {
                break;
            }
        }
        String headerText = header.toString();
        extractAndPrintInfo(filePath.getFileName().toString(), headerText);
    }

    private static void extractAndPrintInfo(String fileName, String headerText) {
        Pattern authorPattern = Pattern.compile("@Author: (.+)");
        Pattern datePattern = Pattern.compile("@Date: (\\d{4}/\\d{2}/\\d{2})");
        Pattern descPattern = Pattern.compile("@Description: (.+)");
        Matcher authorMatcher = authorPattern.matcher(headerText);
        Matcher dateMatcher = datePattern.matcher(headerText);
        Matcher descMatcher = descPattern.matcher(headerText);
        if (authorMatcher.find() && dateMatcher.find() && descMatcher.find()) {
            String author = authorMatcher.group(1);
            String date = dateMatcher.group(1);
            String description = descMatcher.group(1);
            System.out.println("File: " + fileName);
            System.out.println("Author: " + author);
            System.out.println("Date: " + date);
            System.out.println("Description: " + description);
            System.out.println();
        } else {
            System.out.println("File header information not found for: " + fileName);
        }
    }
}

