import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.MalformedURLException;
import java.net.URL;
import java.net.URLConnection;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.TimeUnit;

public class PrintWebContent {
    private static final int MAX_RETRY_ATTEMPTS = 3;
    private static final int CONNECTION_TIMEOUT = 10000; // 10 seconds

    public static void main(String[] args) {
        try {
            // Get the URL from user input
            String urlString = getUserInput();

            // Validate the URL
            if (!isValidURL(urlString)) {
                System.out.println("Invalid URL: " + urlString);
                return;
            }

            // Create a URL object
            URL url = new URL(urlString);

            // Open a connection to the URL with retry mechanism
            URLConnection connection = openConnectionWithRetry(url);
            if (connection == null) {
                System.out.println("Failed to establish connection to the URL.");
                return;
            }

            // Set the connection timeout
            connection.setConnectTimeout(CONNECTION_TIMEOUT);

            // Create a BufferedReader to read the content of the page
            BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream(), getEncoding(connection)));

            // Read and print each line of the page content
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }

            // Close the reader
            reader.close();
        } catch (MalformedURLException e) {
            System.out.println("Invalid URL: " + e.getMessage());
        } catch (IOException e) {
            System.out.println("Error: " + e.getMessage());
        }
    }

    private static String getUserInput() throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        System.out.print("Enter a URL: ");
        String url = reader.readLine();
        return url;
    }

    private static boolean isValidURL(String urlString) {
        try {
            new URL(urlString).toURI();
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    private static URLConnection openConnectionWithRetry(URL url) {
        int retryCount = 0;
        URLConnection connection = null;

        while (retryCount < MAX_RETRY_ATTEMPTS) {
            try {
                connection = url.openConnection();
                return connection;
            } catch (IOException e) {
                retryCount++;
                System.out.println("Failed to establish connection to the URL. Retrying... Attempt: " + retryCount);
                try {
                    TimeUnit.SECONDS.sleep(1);
                } catch (InterruptedException ex) {
                    Thread.currentThread().interrupt();
                }
            }
        }

        return connection;
    }

    private static String getEncoding(URLConnection connection) {
        String contentType = connection.getContentType();
        if (contentType != null) {
            String[] values = contentType.split(";");
            for (String value : values) {
                value = value.trim();
                if (value.toLowerCase().startsWith("charset=")) {
                    return value.substring("charset=".length());
                }
            }
        }
        return StandardCharsets.UTF_8.name(); // Default to UTF-8 if encoding is not specified
    }
}

