import java.util.*;

public class StringOperations {
    public String removeWhitespace(String string) {
        return string.replaceAll("\\s+", "");
    }

    public Map<Character, Integer> countLowercaseLetters(String string) {
        Map<Character, Integer> letterCountMap = new HashMap<>();
        for (char c : string.toCharArray()) {
            if (Character.isLowerCase(c)) {
                letterCountMap.put(c, letterCountMap.getOrDefault(c, 0) + 1);
            }
        }
        return letterCountMap;
    }

    public List<Character> getDescendingOrder(Map<Character, Integer> letterCountMap) {
        List<Character> descendingOrderList = new ArrayList<>();
        for (char c : letterCountMap.keySet()) {
            if (letterCountMap.get(c) > 1) {
                descendingOrderList.add(c);
            }
        }
        descendingOrderList.sort((a, b) -> letterCountMap.get(b) - letterCountMap.get(a));
        return descendingOrderList;
    }

