code:
public class CamelCaseConverter {
   public static void main(String[] args) {
      String str = "This is a Test";
      String camelCaseStr = convertToCamelCase(str);
      System.out.println(camelCaseStr);
   }

   public static String convertToCamelCase(String str) {
      StringBuilder camelCaseStr = new StringBuilder();
      String[] words = str.split(" ");
      for (int i = 0; i < words.length; i++) {
         String word = words[i];
         if (word.length() > 1) {
            word = removeConsecutiveDuplicates(word);
            if (!word.contains("ignore")) {
               word = word.replaceAll("ignore", "");
               camelCaseStr.append(Character.toUpperCase(word.charAt(0)) + word.substring(1).toLowerCase());
            } else {
               camelCaseStr.append(word);
            }
         } else {
            camelCaseStr.append(word.toUpperCase());
         }
         camelCaseStr.append(" ");
      }
      return camelCaseStr.toString().trim();
   }

   public static String removeConsecutiveDuplicates(String str) {
      StringBuilder result = new StringBuilder();
      char prev = '\0';
      for (char c : str.toCharArray()) {
         if (c != prev) {
            result.append(c);
         }
         prev = c;
      }
      return result.toString();
   }
}

