import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;

public class PrimeCalculator implements Callable<List<Integer>> {
    private int start;
    private int end;

    public PrimeCalculator(int start, int end) {
        this.start = start;
        this.end = end;
    }

    public List<Integer> call() {
        List<Integer> primes = new ArrayList<>();
        boolean[] isComposite = new boolean[end + 1];

        for (int i = 2; i <= Math.sqrt(end); i++) {
            if (!isComposite[i]) {
                for (int j = i * i; j <= end; j += i) {
                    isComposite[j] = true;
                }
            }
        }

        for (int i = start; i <= end; i++) {
            if (!isComposite[i]) {
                primes.add(i);
            }
        }

        return primes;
    }
}

public class PrimeSumCalculator {
    public static void main(String[] args) {
        int limit = 100;
        int threadCount = 5;

        List<Integer> allPrimes = new ArrayList<>();

        ExecutorService executorService = Executors.newFixedThreadPool(threadCount);
        List<Future<List<Integer>>> futures = new ArrayList<>();

        int step = limit / threadCount;

        for (int i = 0; i < threadCount; i++) {
            int start = i * step + 1;
            int end = (i == threadCount - 1) ? limit : (i + 1) * step;
            Callable<List<Integer>> task = new PrimeCalculator(start, end);
            Future<List<Integer>> future = executorService.submit(task);
            futures.add(future);
        }

        for (Future<List<Integer>> future : futures) {
            try {
                List<Integer> primes = future.get();
                allPrimes.addAll(primes);
            } catch (InterruptedException | ExecutionException e) {
                e.printStackTrace();
            }
        }

        executorService.shutdown();

        int sum = 0;
        for (int prime : allPrimes) {
            sum += prime;
        }

        System.out.println("Sum of prime numbers up to " + limit + " is: " + sum);
    }
}

