import java.util.ArrayList;
import java.util.List;

public class PrimeNumberGenerator {

    public static void main(String[] args) {
        int n = 100; // Change this value to your desired 'n'
        int sqrtN = (int) Math.sqrt(n);
        int numThreads = Math.min(sqrtN, Runtime.getRuntime().availableProcessors());

        List<Thread> threads = new ArrayList<>();

        int rangeSize = n / numThreads;
        int remainingNumbers = n % numThreads;

        int start = 1;
        int end = start + rangeSize - 1;

        for (int i = 0; i < numThreads; i++) {
            if (i < remainingNumbers) {
                end++;
            }

            Thread thread = new Thread(new PrimeNumberTask(start, end));
            threads.add(thread);
            thread.start();

            start = end + 1;
            end = start + rangeSize - 1;
        }

        for (Thread thread : threads) {
            try {
                thread.join();
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
