import java.util.Scanner;

public class Fibonacci {
    // Function to check if a number is prime
    public static boolean isPrime(int num) {
        if (num <= 1) {
            return false;
        }
        for (int i = 2; i <= Math.sqrt(num); i++) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }

    // Function to round a floating-point number to the nearest integer
    public static int roundToNearestInt(double num) {
        return (int) Math.round(num);
    }

    // Function to generate the Fibonacci sequence up to N using memoization
    public static void generateFibonacci(int num1, int num2, int N) {
        int[] fib = new int[N];
        fib[0] = num1;
        fib[1] = num2;

        for (int i = 2; i < N; i++) {
            fib[i] = fib[i - 1] + fib[i - 2];
        }

        System.out.println("Fibonacci sequence up to " + N + ":");
        for (int i = 0; i < N; i++) {
            System.out.print(fib[i] + " ");
        }
    }

