        Scanner scanner = new Scanner(System.in);
        int num1, num2, N;

        // Input and validation of the first starting number
        while (true) {
            System.out.print("Enter the first starting number: ");
            try {
                double input = scanner.nextDouble();
                num1 = roundToNearestInt(input);
                if (isPrime(num1)) {
                    break;
                } else {
                    System.out.println("Error: The first starting number must be a prime number.");
