                num2 = roundToNearestInt(input);
                if (isPrime(num2)) {
                    break;
                } else {
                    System.out.println("Error: The second starting number must be a prime number.");
                }
            } catch (Exception e) {
                System.out.println("Error: Invalid input. Please enter a valid integer or floating-point number.");
                scanner.nextLine();
            }
        }

        // Input and validation of the target number N
        while (true) {
            System.out.print("Enter the target number N: ");
