public class Node {
    int data;
    Node next;

    public Node(int data) {
        this.data = data;
        this.next = null;
    }
}

public Node deleteNode(Node head, int value) {
    // Initialize current and previous pointers
    Node current = head;
    Node previous = null;

    // Traverse the linked list until the node with the given value is found
    while (current != null && current.data != value) {
        previous = current;
        current = current.next;
    }

    // If the node with the given value is found
    if (current != null) {
        // If the node is the head of the linked list, update the head
        if (previous == null) {
            head = current.next;
        } else {
            // Update the next pointer of the previous node to skip the current node
            previous.next = current.next;
        }

        // Delete the current node
        current = null;
    }

    // Return the modified linked list
    return head;
}

